import{_ as e,o as a,c as l,a0 as s}from"./chunks/framework.DQOulFGV.js";const y=JSON.parse('{"title":"第6章 内存淘汰","description":"","frontmatter":{},"headers":[],"relativePath":"redis/02-standalone-core/chapter-06-eviction.md","filePath":"redis/02-standalone-core/chapter-06-eviction.md"}'),i={name:"redis/02-standalone-core/chapter-06-eviction.md"};function d(n,t,r,o,h,p){return a(),l("div",null,[...t[0]||(t[0]=[s(`<h1 id="第6章-内存淘汰" tabindex="-1">第6章 内存淘汰 <a class="header-anchor" href="#第6章-内存淘汰" aria-label="Permalink to &quot;第6章 内存淘汰&quot;">​</a></h1><blockquote><p>内存是有限的。当 Redis 内存达到上限、又有新数据要写入时，就需要淘汰一部分旧数据。本章讲解 <code>maxmemory</code> 上限、8 种淘汰策略，以及 LRU 与 LFU 算法的差异。</p></blockquote><hr><h2 id="_6-1-maxmemory-配置" tabindex="-1">6.1 maxmemory 配置 <a class="header-anchor" href="#_6-1-maxmemory-配置" aria-label="Permalink to &quot;6.1 maxmemory 配置&quot;">​</a></h2><p><code>maxmemory</code> 是 Redis 允许使用的最大内存，达到上限后触发淘汰。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">maxmemory</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 4gb</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # 内存上限</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">maxmemory-policy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> allkeys-lru</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 淘汰策略</span></span></code></pre></div><p>设置建议：</p><table tabindex="0"><thead><tr><th style="text-align:left;">建议</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">留出余量</td><td style="text-align:left;">设为物理内存的 60%~80%，预留系统与 fork 开销</td></tr><tr><td style="text-align:left;">必须设上限</td><td style="text-align:left;">不设上限时内存会持续增长直到被 OOM 杀死</td></tr><tr><td style="text-align:left;">配合策略</td><td style="text-align:left;">上限 + 淘汰策略配套使用</td></tr></tbody></table><p>当内存达到 <code>maxmemory</code> 时，Redis 根据 <code>maxmemory-policy</code> 指定的策略淘汰键。若策略是 <code>noeviction</code>（不淘汰），则写命令直接报错。</p><hr><h2 id="_6-2-八种淘汰策略" tabindex="-1">6.2 八种淘汰策略 <a class="header-anchor" href="#_6-2-八种淘汰策略" aria-label="Permalink to &quot;6.2 八种淘汰策略&quot;">​</a></h2><p>淘汰策略 = 「淘汰范围」×「淘汰算法」的组合。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>范围：allkeys（所有键） / volatile（只淘汰设置了 TTL 的键）</span></span>
<span class="line"><span>算法：lru / lfu / random / ttl</span></span></code></pre></div><table tabindex="0"><thead><tr><th style="text-align:left;">策略</th><th style="text-align:left;">范围</th><th style="text-align:left;">算法</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>noeviction</code></td><td style="text-align:left;">—</td><td style="text-align:left;">—</td><td style="text-align:left;">不淘汰，写命令报错</td></tr><tr><td style="text-align:left;"><code>allkeys-lru</code></td><td style="text-align:left;">所有键</td><td style="text-align:left;">LRU</td><td style="text-align:left;">淘汰最近最少使用的键</td></tr><tr><td style="text-align:left;"><code>allkeys-lfu</code></td><td style="text-align:left;">所有键</td><td style="text-align:left;">LFU</td><td style="text-align:left;">淘汰使用频率最低的键</td></tr><tr><td style="text-align:left;"><code>allkeys-random</code></td><td style="text-align:left;">所有键</td><td style="text-align:left;">随机</td><td style="text-align:left;">随机淘汰</td></tr><tr><td style="text-align:left;"><code>volatile-lru</code></td><td style="text-align:left;">有 TTL 的键</td><td style="text-align:left;">LRU</td><td style="text-align:left;">淘汰最近最少使用的、有过期时间的键</td></tr><tr><td style="text-align:left;"><code>volatile-lfu</code></td><td style="text-align:left;">有 TTL 的键</td><td style="text-align:left;">LFU</td><td style="text-align:left;">淘汰使用频率最低的、有过期时间的键</td></tr><tr><td style="text-align:left;"><code>volatile-random</code></td><td style="text-align:left;">有 TTL 的键</td><td style="text-align:left;">随机</td><td style="text-align:left;">随机淘汰有过期时间的键</td></tr><tr><td style="text-align:left;"><code>volatile-ttl</code></td><td style="text-align:left;">有 TTL 的键</td><td style="text-align:left;">TTL</td><td style="text-align:left;">淘汰剩余 TTL 最短的键</td></tr></tbody></table><p>选型建议：</p><table tabindex="0"><thead><tr><th style="text-align:left;">场景</th><th style="text-align:left;">推荐策略</th></tr></thead><tbody><tr><td style="text-align:left;">纯缓存（键都有 TTL）</td><td style="text-align:left;"><code>allkeys-lru</code> 或 <code>allkeys-lfu</code></td></tr><tr><td style="text-align:left;">部分键不能丢（永久数据）</td><td style="text-align:left;"><code>volatile-lru</code>（只淘汰有 TTL 的）</td></tr><tr><td style="text-align:left;">访问模式无明显热点</td><td style="text-align:left;"><code>allkeys-random</code></td></tr></tbody></table><hr><h2 id="_6-3-lru-与-lfu" tabindex="-1">6.3 LRU 与 LFU <a class="header-anchor" href="#_6-3-lru-与-lfu" aria-label="Permalink to &quot;6.3 LRU 与 LFU&quot;">​</a></h2><p>LRU（Least Recently Used）与 LFU（Least Frequently Used）是两种主流淘汰算法，衡量标准不同。</p><h3 id="lru-最近最少使用" tabindex="-1">LRU：最近最少使用 <a class="header-anchor" href="#lru-最近最少使用" aria-label="Permalink to &quot;LRU：最近最少使用&quot;">​</a></h3><p>LRU 淘汰「最近一次访问时间最早」的键。适合「近期访问过的数据更可能再次被访问」的场景。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>键 A：最近访问 10 秒前</span></span>
<span class="line"><span>键 B：最近访问 1 小时前</span></span>
<span class="line"><span>→ 淘汰 B（更久没被访问）</span></span></code></pre></div><p>Redis 的 LRU 是<strong>近似 LRU</strong>：随机抽样 N 个键，淘汰其中「最久未访问」的那个，而非精确维护全局有序链表。采样数越大越接近精确 LRU，但 CPU 开销也越大。</p><h3 id="lfu-最不经常使用" tabindex="-1">LFU：最不经常使用 <a class="header-anchor" href="#lfu-最不经常使用" aria-label="Permalink to &quot;LFU：最不经常使用&quot;">​</a></h3><p>LFU 淘汰「访问次数最少」的键。适合「冷热数据分明、需要区分高频与低频」的场景。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>键 A：访问 100 次</span></span>
<span class="line"><span>键 B：访问 2 次</span></span>
<span class="line"><span>→ 淘汰 B（访问次数更少）</span></span></code></pre></div><p>LFU 在 LRU 基础上增加了「访问频率计数」，并引入<strong>衰减机制</strong>：计数随时间递减，避免老热点永远霸占内存、新键无法进入。</p><h3 id="对比" tabindex="-1">对比 <a class="header-anchor" href="#对比" aria-label="Permalink to &quot;对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">LRU</th><th style="text-align:left;">LFU</th></tr></thead><tbody><tr><td style="text-align:left;">衡量标准</td><td style="text-align:left;">最近访问时间</td><td style="text-align:left;">访问频率</td></tr><tr><td style="text-align:left;">适合场景</td><td style="text-align:left;">时间局部性强（最近访问的更可能再访问）</td><td style="text-align:left;">冷热分明（需要区分高频/低频）</td></tr><tr><td style="text-align:left;">缺点</td><td style="text-align:left;">偶发访问会被误判为热点</td><td style="text-align:left;">需要处理计数衰减</td></tr></tbody></table><hr><h2 id="_6-4-内存碎片" tabindex="-1">6.4 内存碎片 <a class="header-anchor" href="#_6-4-内存碎片" aria-label="Permalink to &quot;6.4 内存碎片&quot;">​</a></h2><p>内存碎片指「Redis 实际分配的内存」与「实际使用的内存」之间的差值，通常由频繁的键增删导致。</p><h3 id="查看碎片率" tabindex="-1">查看碎片率 <a class="header-anchor" href="#查看碎片率" aria-label="Permalink to &quot;查看碎片率&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">INFO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> memory</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># used_memory          Redis 实际使用的内存</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># used_memory_rss      操作系统分配给 Redis 的物理内存</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># mem_fragmentation_ratio = rss / used_memory</span></span></code></pre></div><table tabindex="0"><thead><tr><th style="text-align:left;">碎片率</th><th style="text-align:left;">含义</th><th style="text-align:left;">处理</th></tr></thead><tbody><tr><td style="text-align:left;">≈ 1</td><td style="text-align:left;">健康</td><td style="text-align:left;">无需处理</td></tr><tr><td style="text-align:left;">&gt; 1.5</td><td style="text-align:left;">碎片较多</td><td style="text-align:left;">考虑整理</td></tr><tr><td style="text-align:left;">&lt; 1</td><td style="text-align:left;">使用了 swap</td><td style="text-align:left;">内存不足，需扩容</td></tr></tbody></table><h3 id="处理方式" tabindex="-1">处理方式 <a class="header-anchor" href="#处理方式" aria-label="Permalink to &quot;处理方式&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">方式</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">重启</td><td style="text-align:left;">最彻底但影响服务</td></tr><tr><td style="text-align:left;"><code>activedefrag yes</code></td><td style="text-align:left;">在线整理（4.0+，默认关闭，需评估 CPU 开销）</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">activedefrag</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yes</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 开启自动碎片整理</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">active-defrag-ignore-bytes</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 100mb</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 碎片小于 100mb 不整理</span></span></code></pre></div><blockquote><p>碎片整理会消耗 CPU，建议先观察碎片率与 CPU 使用情况再决定是否开启。碎片率高且 CPU 空闲时才值得开启在线整理。</p></blockquote>`,39)])])}const g=e(i,[["render",d]]);export{y as __pageData,g as default};
